<?php
$sql="SELECT ai.*,a.Status ApplicationStatus,s.Name ScholarshipName,u.FirstName,u.LastName,u.StudentID_Num,dr.DocumentName FROM ai_document_analyses ai JOIN application a ON a.ApplicationID=ai.ApplicationID JOIN scholarship s ON s.ScholarshipID=a.ScholarshipID JOIN users u ON u.UserID=a.UserID JOIN submitted_document sd ON sd.SubmittedDocID=ai.SubmittedDocID JOIN document_requirement dr ON dr.RequirementID=sd.RequirementID";$params=[];
if($_SESSION['role']==='Internal_Admin'){$sql.=" LEFT JOIN users cu ON cu.UserID=s.CreatedBy WHERE (cu.Role IS NULL OR cu.Role IN ('Internal_Admin','Super_Admin'))";}
elseif($_SESSION['role']==='External_Admin'){$sql.=' WHERE s.CreatedBy=?';$params[]=$_SESSION['user_id'];}
else{$sql.=' WHERE 1=1';}
$scopeId = (int) ($_GET['scholarship_id'] ?? 0);   // from the Evaluation Center: one scholarship only
if($scopeId){$sql.=' AND a.ScholarshipID=?';$params[]=$scopeId;}
$sql.=" ORDER BY FIELD(ai.ReviewStatus,'Pending','Inconclusive','Overridden','Confirmed'),ai.CreatedAt DESC";$q=$pdo->prepare($sql);$q->execute($params);$analyses=$q->fetchAll(PDO::FETCH_ASSOC);
?>
<main class="flex-1 p-5 lg:p-10 lg:ml-72 bg-slate-50 min-h-screen"><div class="max-w-6xl mx-auto"><header class="mb-8"><p class="text-[11px] font-black uppercase tracking-[.18em] text-purple-600">Human-in-the-loop controls</p><h1 class="text-3xl lg:text-4xl font-black text-slate-900 mt-1">AI Manual Review</h1><p class="text-slate-500 mt-2">AI suggestions never reject an applicant automatically. Every adverse or low-confidence result requires an authorized decision with a reason.</p></header>
<?php if(isset($_SESSION['success'])):?><div class="mb-5 p-4 rounded-xl bg-green-50 border border-green-200 text-green-800 font-bold"><?=htmlspecialchars($_SESSION['success']);unset($_SESSION['success']);?></div><?php endif;?><?php if(isset($_SESSION['error'])):?><div class="mb-5 p-4 rounded-xl bg-red-50 border border-red-200 text-red-800 font-bold"><?=htmlspecialchars($_SESSION['error']);unset($_SESSION['error']);?></div><?php endif;?>
<div class="space-y-5"><?php foreach($analyses as $ai):$fields=json_decode($ai['ExtractedFieldsJson']?:'[]',true);$fails=json_decode($ai['FailedCriteriaJson']?:'[]',true);?><article class="bg-white border <?= $ai['ReviewStatus']==='Pending'?'border-amber-300':'border-slate-200'?> rounded-2xl p-6 shadow-sm"><div class="flex flex-col lg:flex-row justify-between gap-5"><div class="flex-1"><div class="flex flex-wrap gap-2"><span class="px-3 py-1 rounded-full text-[10px] font-black uppercase bg-purple-50 text-purple-700">AI suggestion only</span><span class="px-3 py-1 rounded-full text-[10px] font-black uppercase <?= (float)$ai['OverallConfidence']<80?'bg-amber-100 text-amber-800':'bg-blue-50 text-blue-700'?>"><?=number_format((float)$ai['OverallConfidence'],1)?>% confidence</span><span class="px-3 py-1 rounded-full text-[10px] font-black uppercase bg-slate-100 text-slate-600"><?=htmlspecialchars($ai['ReviewStatus'])?></span></div><h2 class="text-xl font-black text-slate-900 mt-3"><?=htmlspecialchars($ai['FirstName'].' '.$ai['LastName'])?></h2><p class="text-sm text-slate-500"><?=htmlspecialchars($ai['StudentID_Num'].' · '.$ai['ScholarshipName'].' · '.$ai['SourceDocument'])?></p><p class="mt-4 text-sm text-slate-700"><strong>AI explanation:</strong> <?=htmlspecialchars($ai['Explanation']?:'No explanation returned.')?></p><?php foreach($fields as $field):?><div class="mt-3 bg-blue-50 border border-blue-100 rounded-xl p-3 text-sm"><strong><?=htmlspecialchars($field['label']??'Extracted field')?>:</strong> <?=htmlspecialchars((string)($field['value']??'N/A'))?><br><span class="text-xs text-blue-700">Source: <?=htmlspecialchars(($field['source_document']??$ai['SourceDocument']).' → '.($field['source_field']??'unspecified field'))?> · <?=number_format((float)($field['confidence']??0),1)?>%</span></div><?php endforeach;?><?php if($fails):?><div class="mt-3 bg-red-50 border border-red-100 rounded-xl p-3"><p class="text-xs font-black uppercase text-red-700 mb-2">Failed criteria</p><?php foreach($fails as $fail):?><p class="text-sm text-red-800">• <?=htmlspecialchars($fail['criterion']??'Criterion')?> — <?=htmlspecialchars($fail['explanation']??'Not met')?></p><?php endforeach;?></div><?php endif;?></div>
<?php if($ai['ReviewStatus']==='Pending'||$ai['ReviewStatus']==='Inconclusive'):?><form method="post" action="../actions/process_ai_review.php" class="lg:w-96 bg-slate-50 rounded-2xl p-4"><input type="hidden" name="analysis_id" value="<?=(int)$ai['AnalysisID']?>"><label class="text-xs font-black uppercase text-slate-500">Authorized decision<select name="decision" required class="mt-2 w-full rounded-xl border border-slate-200 p-3"><option value="">Select…</option><option>Verify Document</option><option>Request Correction</option><option>Inconclusive</option></select></label><label class="block mt-3 text-xs font-black uppercase text-slate-500">Manual findings / override reason<textarea name="reason" required minlength="10" rows="4" class="mt-2 w-full rounded-xl border border-slate-200 p-3 text-sm" placeholder="Explain the evidence used for the human decision"></textarea></label><button class="mt-3 w-full bg-slate-900 text-white rounded-xl py-3 text-xs font-black uppercase tracking-widest">Record manual decision</button></form><?php else:?><div class="lg:w-96 bg-green-50 border border-green-100 rounded-2xl p-4"><p class="text-xs font-black uppercase text-green-700">Manual decision</p><p class="font-black mt-2"><?=htmlspecialchars($ai['ManualDecision'])?></p><p class="text-sm text-slate-600 mt-2"><?=htmlspecialchars($ai['OverrideReason'])?></p></div><?php endif;?></div></article><?php endforeach;?><?php if(!$analyses):?><div class="bg-white rounded-2xl border border-slate-200 p-12 text-center text-slate-500">No AI analyses have been run yet.</div><?php endif;?></div></div></main>
